  "spark": { t: "bolt" }, "ember-dart": { t: "bolt" }, "force-pebble": { t: "bolt" }, "arcane-bolt": { t: "bolt" }, "mana-needle": { t: "bolt" },
  "chill-touch": { t: "bolt", st: { id: "noheal", name: "Withered", rounds: 1, noheal: 1 } },
  "radiant-brand": { t: "bolt", vsHoly: [1, 4] },
