  "guardian-halo": { t: "aura", allies: true, st: { id: "halo", name: "Guardian Halo", rounds: 5, dr: 1, noFear: 1 }, radius: 10 * FT },
  "rallying-chorus": { t: "aura", allies: true, st: { id: "rally", name: "Rallying Chorus", rounds: 1, atk: 1 }, radius: 20 * FT },
