.eSlots{display:flex;gap:4px;padding:6px 8px;background:linear-gradient(180deg,rgba(18,21,27,.92),rgba(6,7,9,.92));border:1px solid var(--e-line);box-shadow:0 0 0 1px #000,0 6px 20px rgba(0,0,0,.6)}
